        "LV-ARCH-704": "32ddd24477b1a0ac378c82ae4d9809d0e9deb1bea6f5d4e087c948281b8bbd19",
    }
    unrelated_ok = len(unrelated) == len(baseline_unrelated_hashes)
    for row in unrelated:
        digest = hashlib.sha256(json.dumps(dict(row), sort_keys=True, separators=(",", ":")).encode()).hexdigest()
        unrelated_ok = unrelated_ok and baseline_unrelated_hashes.get(row["leave_id"]) == digest
    if duplicate_ok and canonical_ok and unrelated_ok:
        return _result(1, "Duplicate row identity metadata and unrelated rows match baseline")
    return _result(0, f"Preservation failure: duplicate={duplicate_ok}, canonical={canonical_ok}, unrelated={unrelated_ok}")
